 const items=await Promise.all(ps.map(async p=>{const mine=ups.filter(x=>x.planId===p.id);return Object.assign(await planOut(p,D),{purchases:mine.length,activeRecords:mine.filter(x=>x.status==='active'&&(!x.expiresAt||x.expiresAt>t)).length,totalClaimed:L.toNum(mine.reduce((s,x)=>s+x.earned,0),D[p.rewardCurrency]==null?2:D[p.rewardCurrency])})}));
